/// Execute a prepared UPDATE/INSERT/DELETE statement that has already had parameters bound.
///
/// This should only be called after `do_put_update` has been called to bind parameters.
/// Returns the number of affected rows.
pub(crate) async fn do_get(
    query: sql::CommandPreparedStatementUpdate,
) -> Result<Response<<Service as FlightService>::DoGetStream>, Status> {
    let _start = metrics::track_flight_request("do_get", Some("prepared_statement_update")).await;
    set_flightsql_protocol().await;

    let context = RequestContext::current(AsyncMarker::new().await);
    let datafusion = get_current_datafusion(&context);

    if is_auth_read_only(&context) {
        return Err(Status::permission_denied(
            "Write access denied. Verify that authentication key used has write access and try again.",
        ));
    }

    tracing::trace!("do_get_prepared_statement_update: {query:?}");

    let PreparedStatement {
        query: sql,
        parameters,
        parameter_schema: _,
    } = from_bytes(&query.prepared_statement_handle).map_err(error_to_status)?;

    let parameters = decode_param_values(&parameters).map_err(param_error_to_status)?;

    // Execute through the standard query path, which handles DELETE and UPDATE
    // via the runtime's DML interception in Query::run().
    let query_result = QueryBuilder::new(&sql, datafusion)
        .parameters(parameters)
        .build()
        .run()
        .await
        .map_err(handle_query_error)?;

/// Bind the parameters from the [`FlightData`] to the prepared UPDATE statement.
///
/// This is identical to the query parameter binding, but handles UPDATE statements.
/// See [Sequence Diagrams](https://arrow.apache.org/docs/format/FlightSql.html#sequence-diagrams)
pub(crate) async fn do_put_update(
    query: CommandPreparedStatementUpdate,
    streaming_flight: Peekable<Streaming<FlightData>>,
) -> Result<Response<<Service as FlightService>::DoPutStream>, Status> {
    let _start = metrics::track_flight_request("do_put", Some("prepared_statement_update")).await;
    let decodable = DecodableSchema::default();
    let streaming_flight = streaming_flight.map({
        let decodable = decodable.clone();
        move |flight_data| {
            flight_data
                .map_err(|status| FlightError::Tonic(Box::new(status)))
                .map(|message| decodable.repair(message))
        }
    });

    let mut decoder = FlightDataDecoder::new(streaming_flight);
    let schema = decodable.declared(decode_schema(&mut decoder).await?);

    // Bound the same way the query path binds: what is stored is what the statement will run
    // with, so a `MAP` whose `entries` the client declared nullable is brought into line before
    // it is written rather than at the next execution.
    let normalizer = MapEntriesNormalizer::for_schema(&schema);
    let parameters = encode_single_row_parameters(&mut decoder, &normalizer).await?;

    let mut stmt: PreparedStatement =
        from_bytes(&query.prepared_statement_handle).map_err(error_to_status)?;
    stmt.parameters = parameters;
    let handle = to_stdvec(&stmt).map_err(error_to_status)?;

    let result = DoPutPreparedStatementResult {
        prepared_statement_handle: Some(handle.into()),
    };

    let output = futures::stream::iter(vec![Ok(PutResult {
        app_metadata: result.encode_to_vec().into(),
    })]);
    Ok(Response::new(Box::pin(output)))

let (res_stream, physical_plan): (
    SendableRecordBatchStream,
    Arc<dyn ExecutionPlan>,
) = if matches!(&*plan, LogicalPlan::Statement(_)) {
    // For Statement plans, use SessionContext::execute_logical_plan()
    // which handles PREPARE/EXECUTE/DEALLOCATE by modifying session state.
    // Use the session-specific context if available to ensure prepared statements
    // are scoped to individual sessions.
    let session_ctx = if let Some(flight_session) =
        owned_flight_session(&request_context)
    {
