            "Statement plan using ad-hoc session (no Flight session, or the session is not owned by this principal)"
        );
        Arc::new(SessionContext::new_with_state(ctx.df.ctx.state()))
    };

    Self::ensure_not_cancelled(&query_cancel_token, &query_id_str, &timeout_state)?;
    let dataframe = match session_ctx
        .execute_logical_plan(plan.as_ref().clone())
        .await
    {
        Ok(df) => df,
        Err(e) => {
            let e = find_datafusion_root(e);
            let error_code = ErrorCode::from(&e);
            handle_error!(
                tracker,
                &request_context,
                error_code,
                e,
                UnableToExecuteQuery
            )
        }
    };

// Advertise the schema after the analyzer has applied type coercion,
// but before logical optimizer rules run. Execution also analyzes the
// plan before planning, so using the raw logical schema here can make
// FlightSQL GetFlightInfo disagree with DoGet for expressions such as
// `CASE WHEN ... THEN decimal_col ELSE 0 END`.
//
// Analyzed against the session's state in place: the analyzer reads only
// its configuration, and copying the state copies every registered
// function. Nothing is awaited while the state is read.
let analyzed_plan = {
    let state = session_ctx.state_ref();
    let state = state.read();
    state
        .analyzer()
        .execute_and_check(*plan, state.config_options(), |_, _| {})
};
let analyzed_plan = match analyzed_plan {
    Ok(plan) => plan,
    Err(e) => {
        let e = find_datafusion_root(e);
        self.handle_schema_error(&request_context, &e);
        return Err(e);
    }
};

let dataset_schema = analyzed_plan.schema().as_arrow().clone();
let parameter_schema = parameter_schema_for_plan(&analyzed_plan)?;

Ok((dataset_schema, parameter_schema))

fn parameter_schema_for_plan(plan: &LogicalPlan) -> Result<Option<Schema>, DataFusionError> {
    let mut parameters: Vec<(String, arrow_schema::DataType)> = plan
        .get_parameter_types()?
        .into_iter()
        .map(|(name, dt)| {
            // If cannot determine datatype, we are assuming UInt64.
            // This occurs for LIMIT/OFFSET parameters such as for:
            // ```sql
            // SELECT * FROM table LIMIT $1
            // ```
            // The plan types such an operand as Int64, but type coercion has already
            // cast it to Int64 by the time this runs, and the cast is what is left
            // here in place of the placeholder itself. Other cases are not known.
            (name, dt.unwrap_or(arrow_schema::DataType::UInt64))
        })
        .collect();

    // Sort parameters by their numeric value to ensure correct ordering
    // For example, $1, $2, ..., $9, $10, $11 instead of $1, $10, $11, $2, ...
    parameters.sort_by(|a, b| {
        let parse_param_num =
            |param_name: &str| -> Option<u32> { param_name.strip_prefix('$')?.parse().ok() };

        let a_num = parse_param_num(&a.0);
        let b_num = parse_param_num(&b.0);

        match (a_num, b_num) {
            (Some(a), Some(b)) => a.cmp(&b),
            (Some(_), None) => std::cmp::Ordering::Less, // numeric params come before non-numeric
            (None, Some(_)) => std::cmp::Ordering::Greater,
            (None, None) => a.0.cmp(&b.0), // fallback to lexicographic for non-numeric params
        }
    });

    let maybe_schema = if parameters.is_empty() {
        None
    } else {
        let mut builder = SchemaBuilder::new();
        for (name, typ) in parameters {
            builder.push(Field::new(name, typ, false));
        }
        Some(builder.finish())
    };

    Ok(maybe_schema)

/// Binds a request to the Flight SQL session its `x-session-id` header or
/// Bearer token names, creating the session — owned by the request's
/// principal — if it does not exist.
///
/// Must run after authentication. The session id is client-controlled and an
/// unknown id creates a session, so when an authenticator is configured only a
/// request with an authenticated principal is bound; otherwise any client could
/// fill the bounded session store and evict authenticated sessions, whose
/// Bearer tokens then stop authenticating.

// With an authenticator configured, only `Handshake` reaches this layer
// unauthenticated, and it creates its own session.
let principal = req
    .extensions()
    .get::<Arc<dyn AuthRequestContext + Send + Sync>>()
    .and_then(|context| context.auth_principal());
let authenticated = principal.is_some();
let principal_stable_id =
    principal.and_then(|principal| principal.stable_id().map(Cow::into_owned));

if (authenticated || !self.auth_configured)
    && let Some(request_context) = req.extensions().get::<Arc<RequestContext>>()
    && let Some(session) = self.session_store.get_or_create_session_from_http(
        req.headers(),
        &self.df.ctx,
        principal_stable_id.as_deref(),
    )
{
    request_context.insert_extension(FlightSessionExtension::new(
        session.context,
        session.owner_stable_id,
    ));
}

/** Construct a signature. */
static Signature newSignature(final String sql, Schema resultSetSchema, Schema parameterSchema) {
  List<ColumnMetaData> columnMetaData =
      resultSetSchema == null
          ? new ArrayList<>()
          : ConvertUtils.convertArrowFieldsToColumnMetaDataList(resultSetSchema.getFields());
  List<AvaticaParameter> parameters =
      parameterSchema == null
          ? new ArrayList<>()
          : ConvertUtils.convertArrowFieldsToAvaticaParameters(parameterSchema.getFields());
  StatementType statementType =
      resultSetSchema == null || resultSetSchema.getFields().isEmpty()
          ? StatementType.IS_DML
          : StatementType.SELECT;
  return new Signature(
      columnMetaData,
      sql,
      parameters,
      Collections.emptyMap(),
      null, // unnecessary, as SQL requests use ArrowFlightJdbcCursor
      statementType);

public ExecuteResult execute(
    final StatementHandle statementHandle,
    final List<TypedValue> typedValues,
    final long maxRowCount) {
  Preconditions.checkArgument(
      connection.id.equals(statementHandle.connectionId), "Connection IDs are not consistent");
  PreparedStatement preparedStatement = getPreparedStatement(statementHandle);

  if (preparedStatement == null) {
    throw new IllegalStateException("Prepared statement not found: " + statementHandle);
  }

  new AvaticaParameterBinder(
          preparedStatement, ((ArrowFlightConnection) connection).getBufferAllocator())
      .bind(typedValues);

  if (statementHandle.signature == null
      || statementHandle.signature.statementType == StatementType.IS_DML) {
    // Update query
    long updatedCount = preparedStatement.executeUpdate();
    return new ExecuteResult(
        Collections.singletonList(
            MetaResultSet.count(statementHandle.connectionId, statementHandle.id, updatedCount)));

public ExecuteResult prepareAndExecute(
    final StatementHandle handle,
    final String query,
    final long maxRowCount,
    final int maxRowsInFirstFrame,
    final PrepareCallback callback)
    throws NoSuchStatementException {
  try {
    PreparedStatement preparedStatement = prepareForHandle(query, handle);
    final StatementType statementType = preparedStatement.getType();

    final long updateCount =
        statementType.equals(StatementType.UPDATE) ? preparedStatement.executeUpdate() : -1;
    synchronized (callback.getMonitor()) {
      callback.clear();
      callback.assign(handle.signature, null, updateCount);
    }
    callback.execute();
    final MetaResultSet metaResultSet =
        MetaResultSet.create(handle.connectionId, handle.id, false, handle.signature, null);

public PreparedStatement prepare(final String query) {
  final FlightSqlClient.PreparedStatement preparedStatement =
      sqlClient.prepare(query, getOptions());
  return new PreparedStatement() {
    @Override
    public FlightInfo executeQuery() throws SQLException {
      return preparedStatement.execute(getOptions());
    }

    @Override
    public long executeUpdate() {
      return preparedStatement.executeUpdate(getOptions());
    }

    @Override
    public StatementType getType() {
      final Schema schema = preparedStatement.getResultSetSchema();
      return schema.getFields().isEmpty() ? StatementType.UPDATE : StatementType.SELECT;
    }

    @Override
    public Schema getDataSetSchema() {
      return preparedStatement.getResultSetSchema();
    }

    @Override
    public Schema getParameterSchema() {
      return preparedStatement.getParameterSchema();
    }

    @Override
    public void setParameters(VectorSchemaRoot parameters) {
      preparedStatement.setParameters(parameters);
    }

    @Override
    public void close() {
      try {
        preparedStatement.close(getOptions());
      } catch (FlightRuntimeException fre) {
        handleBenignCloseException(fre, "closing PreparedStatement");
      }
    }

/**
 * Convert Avatica PreparedStatement parameters from a list of TypedValue to Arrow and bind them to
 * the VectorSchemaRoot representing the PreparedStatement parameters.
 *
 * <p>NOTE: Make sure to close the parameters VectorSchemaRoot once we're done with them.
 */
public class AvaticaParameterBinder {
  private final PreparedStatement preparedStatement;
  private final VectorSchemaRoot parameters;

  /**
   * Instantiate a new AvaticaParameterBinder.
   *
   * @param preparedStatement The PreparedStatement to bind parameters to.
   * @param bufferAllocator The BufferAllocator to use for allocating memory.
   */
  public AvaticaParameterBinder(
      PreparedStatement preparedStatement, BufferAllocator bufferAllocator) {
    this.parameters =
        VectorSchemaRoot.create(preparedStatement.getParameterSchema(), bufferAllocator);
    this.preparedStatement = preparedStatement;
  }

  /**
   * Bind the given Avatica values to the prepared statement.
   *
   * @param typedValues The parameter values.
   */
  public void bind(List<TypedValue> typedValues) {
    bind(typedValues, 0);
  }

  /**
   * Bind the given Avatica values to the prepared statement at the given index.
   *
   * @param typedValues The parameter values.
   * @param index index for parameter.
   */
  public void bind(List<TypedValue> typedValues, int index) {
    if (preparedStatement.getParameterSchema().getFields().size() != typedValues.size()) {
      throw new IllegalStateException(
          String.format(
              "Prepared statement has %s parameters, but only received %s",
              preparedStatement.getParameterSchema().getFields().size(), typedValues.size()));
    }

    for (int i = 0; i < typedValues.size(); i++) {
      bind(parameters.getVector(i), typedValues.get(i), index);
    }

    if (!typedValues.isEmpty()) {
      parameters.setRowCount(index + 1);
      preparedStatement.setParameters(parameters);
    }

private void bind(FieldVector vector, @Nullable TypedValue typedValue, int index) {
  try {
    if (typedValue == null || typedValue.value == null) {
      if (vector.getField().isNullable()) {
        vector.setNull(index);
      } else {
        throw new UnsupportedOperationException("Can't set null on non-nullable parameter");
      }
    } else if (!vector
        .getField()
        .getType()
        .accept(new BinderVisitor(vector, typedValue, index))) {
      throw new UnsupportedOperationException(
          String.format("Binding to vector type %s is not yet supported", vector.getClass()));
    }
  } catch (ClassCastException e) {
    throw new UnsupportedOperationException(
        String.format(
            "Binding value of type %s is not yet supported for expected Arrow type %s",
            typedValue == null ? "null" : typedValue.type, vector.getField().getType()));
  }

@Override
public void close() throws SQLException {
  Exception topLevelException = null;
  try {
    if (executorService != null) {
      executorService.shutdown();
    }
  } catch (final Exception e) {
    topLevelException = e;
  }
  // copies of the collections are used to avoid concurrent modification problems
  ArrayList<AutoCloseable> closeables = new ArrayList<>(statementMap.values());
  closeables.addAll(new ArrayList<>(metadataResultSetMap.values()));
  closeables.add(clientHandler);
  closeables.addAll(allocator.getChildAllocators());
  closeables.add(allocator);
  try {
    AutoCloseables.close(closeables);
  } catch (final Exception e) {
    if (topLevelException == null) {
      topLevelException = e;
    } else {
      topLevelException.addSuppressed(e);
    }
  }
  try {
    super.close();
  } catch (final Exception e) {
    if (topLevelException == null) {
      topLevelException = e;
    } else {
      topLevelException.addSuppressed(e);
    }

public void setParameters(final VectorSchemaRoot parameterBindingRoot) {
  if (parameterBindingRoot == this.parameterBindingRoot) {
    // Nothing to do if we're attempting to set the same parameters again.
    return;
  }
  clearParameters();
  this.parameterBindingRoot = parameterBindingRoot;
}

/**
 * Closes the {@link #parameterBindingRoot}, which contains the parameter binding from a {@link
 * PreparedStatement} operation, releasing its resources.
 */
public void clearParameters() {
  if (parameterBindingRoot != null) {
    parameterBindingRoot.close();
  }

public long executeUpdate(final CallOption... options) {
  checkOpen();
  final FlightDescriptor descriptor =
      FlightDescriptor.command(
          Any.pack(
                  CommandPreparedStatementUpdate.newBuilder()
                      .setPreparedStatementHandle(
                          preparedStatementResult.getPreparedStatementHandle())
                      .build())
              .toByteArray());
  setParameters(parameterBindingRoot == null ? VectorSchemaRoot.of() : parameterBindingRoot);
  SyncPutListener putListener = putParameters(descriptor, options);

  try {
    final PutResult read = putListener.read();
    try (final ArrowBuf metadata = read.getApplicationMetadata()) {
      final DoPutUpdateResult doPutUpdateResult =
          DoPutUpdateResult.parseFrom(metadata.nioBuffer());
      return doPutUpdateResult.getRecordCount();
    }
  } catch (final InterruptedException e) {
    throw CallStatus.CANCELLED.withCause(e).toRuntimeException();
  } catch (final ExecutionException e) {
    throw CallStatus.CANCELLED.withCause(e.getCause()).toRuntimeException();
  } catch (final InvalidProtocolBufferException e) {
    throw CallStatus.INTERNAL.withCause(e).toRuntimeException();
  }

public void close(final CallOption... options) {
  if (isClosed) {
    return;
  }
  isClosed = true;
  final Action action =
      new Action(
          FlightSqlUtils.FLIGHT_SQL_CLOSE_PREPARED_STATEMENT.getType(),
          Any.pack(
                  ActionClosePreparedStatementRequest.newBuilder()
                      .setPreparedStatementHandle(
                          preparedStatementResult.getPreparedStatementHandle())
                      .build())
              .toByteArray());
  final Iterator<Result> closePreparedStatementResults = client.doAction(action, options);
  closePreparedStatementResults.forEachRemaining(result -> {});
  clearParameters();
}
